package local.skyfamily;
import android.app.AlertDialog;import android.text.InputFilter;import android.widget.*;import java.util.*;
final class ReceiverNameSettings {
 static void add(PersonalActivity host){host.section("DLNA receiver name");host.text("Saved on this device and shown to DLNA senders such as BubbleUPnP. Applying a changed name restarts receiver discovery and ends a loaded cast after confirmation.");EditText input=host.input("DLNA device name",host.prefs.getString("dlna.name","legacydash"));input.setSingleLine(true);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(64)});TextView status=host.paperText("Saved name: "+host.prefs.getString("dlna.name","legacydash"),15,PaperActivity.MUTE);host.body.addView(status);host.button("Save and apply DLNA name",()->{String name=input.getText().toString().trim();if(name.isEmpty()||name.length()>64){host.toast("Enter a name with 1-64 characters");return;}for(int i=0;i<name.length();i++)if(Character.isISOControl(name.charAt(i))){host.toast("Name cannot contain control characters");return;}if(name.equals(host.prefs.getString("dlna.name","legacydash"))){status.setText("Name unchanged: "+name);return;}CastService service=CastService.instance;if(service!=null&&service.active!=null&&!service.active.uri.isEmpty())new AlertDialog.Builder(host).setTitle("Apply receiver name?").setMessage("Save the receiver name as \""+name+"\"? Applying it ends the currently loaded cast and refreshes DLNA discovery.").setPositiveButton("Save and apply",(dialog,which)->apply(host,name,status)).setNegativeButton("Cancel",null).show();else apply(host,name,status);});}
 static void apply(PersonalActivity host,String name,TextView status){if(!host.prefs.edit().putString("dlna.name",name).commit()){status.setText("Name NOT SAVED / check device storage");return;}CastService service=CastService.instance;if(service==null){if(host.prefs.getBoolean("cast.persistent",true))host.startCast();status.setText("Saved: "+name+" / used when receiver starts");return;}try{service.stopForExit();for(UpnpRenderer receiver:new ArrayList<UpnpRenderer>(service.receivers.values()))receiver.close();service.receivers.clear();service.active=null;service.nextScan=0;service.scan();status.setText("Saved: "+name+(service.receivers.isEmpty()?" / receiver waiting for network; refresh sender devices":" / discovery restarted; refresh devices in your sender"));}catch(Exception error){status.setText("Name saved: "+name+" / receiver refresh failed; disable and enable it in Cast setup");}}
}
